-- 세트 602. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set602.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 602, 'CPU·메모리 오버커밋 계산: vCPU 비율, 메모리 할당률, balloon 회수량, KSM 절약량', 'VM 을 많이 올릴 때 자원이 얼마나 약속(오버커밋)되었는지 계산해 보는 연습입니다. 호스트의 논리 CPU 수와 VM 들의 vCPU 합으로 CPU 오버커밋 비율을, VM 메모리 합과 호스트 메모리로 할당률을, balloon 으로 회수한 메모리를, KSM 이 중복 페이지를 합쳐 아낀 메모리를 계산하고, 오버커밋이 지나칠 때의 증상(steal, 스왑·OOM)을 정리합니다. 샌드박스에는 libvirt 가 없어 샘플 출력으로 계산합니다.', 'linux', '가상화'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 602);
UPDATE quest_set SET display_order = 862, unit_id = (SELECT id FROM unit WHERE id = 48), icon = '🧮' WHERE id = 602;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 1, 'vCPU 합계', '`/tmp/vm_list.log` 는 여러 도구에서 모은 호스트의 VM 목록(샘플)입니다. 모든 VM 의 **vCPU 합계**를 숫자만 `/tmp/vcpu_sum.txt` 에 저장하세요.', '헤더 줄을 제외하고 vCPU 열을 모두 더하세요. `awk` 로 합계를 낼 수 있습니다.', 'cat /tmp/vm_list.log
awk ''NR>1 {s += $2} END {print s}'' /tmp/vm_list.log > /tmp/vcpu_sum.txt
cat /tmp/vcpu_sum.txt

# 4 + 8 + 24 + 4 = 40. 호스트 논리 CPU 는 32 개라 vCPU 가 물리보다 많다(오버커밋). VM 이 동시에 꽉 쓰지 않으면 문제가 없지만 몰리면 steal 이 늘어난다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nEOF\\ncat > /tmp/free.log <<''EOF''\\n              total        used        free      shared  buff/cache   available\\nMem:         131072       72000       30000        1200       29000       57000\\nSwap:          8192           0        8192\\nEOF\\ncat > /tmp/vm_list.log <<''EOF''\\n Name    vCPU  Memory(MiB)  State\\n web01      4        8192   running\\n db01       8       32768   running\\n batch     24       16384   running\\n cache      4        8192   running\\nEOF\\ncat > /tmp/db01_info.log <<''EOF''\\nMax memory:     33554432 KiB\\nUsed memory:    16777216 KiB\\nEOF\\ncat > /tmp/ksm.log <<''EOF''\\npages_shared 1000\\npages_sharing 8000\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/vcpu_sum.txt)\\" = 40 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "40 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/vcpu_sum.txt)\\" = 40 ]"]}]', '[{"title": "libvirt 메모리 balloon", "url": "https://libvirt.org/formatdomain.html#memory-balloon-device"}, {"title": "KSM 문서", "url": "https://docs.kernel.org/admin-guide/mm/ksm.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 2, 'CPU 오버커밋 비율', '호스트의 논리 CPU 수는 `/tmp/lscpu.log` 로 구합니다(소켓 × 소켓당 코어 × 코어당 스레드). **vCPU 합계 ÷ 논리 CPU 수** 를 **100 배한 정수**(소수점 이하 버림, 1.25 → 125)로 `/tmp/cpu_ratio.txt` 에 저장하세요.', '논리 CPU 는 세 값의 곱이고 vCPU 합계는 앞 문제와 같습니다. 곱하기 100 을 먼저 하고 나누세요.', 'S=$(grep ''^Socket'' /tmp/lscpu.log | awk ''{print $2}'')
C=$(grep ''^Core'' /tmp/lscpu.log | awk ''{print $4}'')
T=$(grep ''^Thread'' /tmp/lscpu.log | awk ''{print $4}'')
V=$(awk ''NR>1 {s += $2} END {print s}'' /tmp/vm_list.log)
echo $((V * 100 / (S * C * T))) > /tmp/cpu_ratio.txt
cat /tmp/cpu_ratio.txt

# 40/32 = 1.25 배. 일반 업무 서버는 3~4 배까지도 쓰지만 CPU 를 꽉 쓰는 워크로드는 1~2 배 이내로 잡는다. steal 시간으로 판단한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nEOF\\ncat > /tmp/free.log <<''EOF''\\n              total        used        free      shared  buff/cache   available\\nMem:         131072       72000       30000        1200       29000       57000\\nSwap:          8192           0        8192\\nEOF\\ncat > /tmp/vm_list.log <<''EOF''\\n Name    vCPU  Memory(MiB)  State\\n web01      4        8192   running\\n db01       8       32768   running\\n batch     24       16384   running\\n cache      4        8192   running\\nEOF\\ncat > /tmp/db01_info.log <<''EOF''\\nMax memory:     33554432 KiB\\nUsed memory:    16777216 KiB\\nEOF\\ncat > /tmp/ksm.log <<''EOF''\\npages_shared 1000\\npages_sharing 8000\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/cpu_ratio.txt)\\" = 125 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "125 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/cpu_ratio.txt)\\" = 125 ]"]}]', '[{"title": "libvirt 메모리 balloon", "url": "https://libvirt.org/formatdomain.html#memory-balloon-device"}, {"title": "KSM 문서", "url": "https://docs.kernel.org/admin-guide/mm/ksm.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 3, '메모리 할당 합계', '같은 목록에서 모든 VM 에 **할당한 메모리의 합계(MiB)** 를 숫자만 `/tmp/mem_sum.txt` 에 저장하세요.', 'Memory(MiB) 열을 모두 더하세요.', 'awk ''NR>1 {s += $3} END {print s}'' /tmp/vm_list.log > /tmp/mem_sum.txt
cat /tmp/mem_sum.txt

# 8192 + 32768 + 16384 + 8192 = 65536MiB(64GiB). 호스트 메모리는 128GiB 라 절반이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nEOF\\ncat > /tmp/free.log <<''EOF''\\n              total        used        free      shared  buff/cache   available\\nMem:         131072       72000       30000        1200       29000       57000\\nSwap:          8192           0        8192\\nEOF\\ncat > /tmp/vm_list.log <<''EOF''\\n Name    vCPU  Memory(MiB)  State\\n web01      4        8192   running\\n db01       8       32768   running\\n batch     24       16384   running\\n cache      4        8192   running\\nEOF\\ncat > /tmp/db01_info.log <<''EOF''\\nMax memory:     33554432 KiB\\nUsed memory:    16777216 KiB\\nEOF\\ncat > /tmp/ksm.log <<''EOF''\\npages_shared 1000\\npages_sharing 8000\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/mem_sum.txt)\\" = 65536 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "65536 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/mem_sum.txt)\\" = 65536 ]"]}]', '[{"title": "libvirt 메모리 balloon", "url": "https://libvirt.org/formatdomain.html#memory-balloon-device"}, {"title": "KSM 문서", "url": "https://docs.kernel.org/admin-guide/mm/ksm.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 4, '메모리 할당률', '`/tmp/free.log` 는 호스트의 `free -m` 출력입니다. **VM 에 할당한 메모리 합계 ÷ 호스트 전체 메모리(`total`)** 를 **백분율 정수**(소수점 이하 버림)로 `/tmp/mem_pct.txt` 에 저장하세요.', '`Mem:` 줄의 첫 번째 숫자가 total 입니다. 앞 문제의 합계와 계산하세요.', 'cat /tmp/free.log
T=$(grep ''^Mem:'' /tmp/free.log | awk ''{print $2}'')
M=$(awk ''NR>1 {s += $3} END {print s}'' /tmp/vm_list.log)
echo $((M * 100 / T)) > /tmp/mem_pct.txt
cat /tmp/mem_pct.txt

# 50%. 메모리는 CPU 와 달리 부족하면 스왑·OOM kill 로 이어져 오버커밋을 보수적으로 잡는다(보통 100% 이하 권장). 호스트 자신과 캐시 몫도 남겨 둔다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nEOF\\ncat > /tmp/free.log <<''EOF''\\n              total        used        free      shared  buff/cache   available\\nMem:         131072       72000       30000        1200       29000       57000\\nSwap:          8192           0        8192\\nEOF\\ncat > /tmp/vm_list.log <<''EOF''\\n Name    vCPU  Memory(MiB)  State\\n web01      4        8192   running\\n db01       8       32768   running\\n batch     24       16384   running\\n cache      4        8192   running\\nEOF\\ncat > /tmp/db01_info.log <<''EOF''\\nMax memory:     33554432 KiB\\nUsed memory:    16777216 KiB\\nEOF\\ncat > /tmp/ksm.log <<''EOF''\\npages_shared 1000\\npages_sharing 8000\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/mem_pct.txt)\\" = 50 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "50 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/mem_pct.txt)\\" = 50 ]"]}]', '[{"title": "libvirt 메모리 balloon", "url": "https://libvirt.org/formatdomain.html#memory-balloon-device"}, {"title": "KSM 문서", "url": "https://docs.kernel.org/admin-guide/mm/ksm.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 5, 'balloon 이 회수한 메모리', '`/tmp/db01_info.log` 는 VM `db01` 의 `Max memory`(상한)와 `Used memory`(지금 게스트에 준 양)입니다. 호스트가 balloon 으로 **회수한 메모리**를 **MiB** 로 환산해 숫자만 `/tmp/reclaimed.txt` 에 저장하세요. (두 값은 KiB 단위)', '두 값의 차이를 구하고 1024 로 나누세요.', 'cat /tmp/db01_info.log
M=$(grep ''Max memory'' /tmp/db01_info.log | awk ''{print $3}'')
U=$(grep ''Used memory'' /tmp/db01_info.log | awk ''{print $3}'')
echo $(( (M - U) / 1024 )) > /tmp/reclaimed.txt
cat /tmp/reclaimed.txt

# 16384MiB(16GiB)를 회수했다. 게스트가 실제로 그 메모리를 쓰고 있으면 게스트 안에서 스왑·OOM 이 발생하므로 balloon 은 여유가 있는 VM 에서만 쓴다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nEOF\\ncat > /tmp/free.log <<''EOF''\\n              total        used        free      shared  buff/cache   available\\nMem:         131072       72000       30000        1200       29000       57000\\nSwap:          8192           0        8192\\nEOF\\ncat > /tmp/vm_list.log <<''EOF''\\n Name    vCPU  Memory(MiB)  State\\n web01      4        8192   running\\n db01       8       32768   running\\n batch     24       16384   running\\n cache      4        8192   running\\nEOF\\ncat > /tmp/db01_info.log <<''EOF''\\nMax memory:     33554432 KiB\\nUsed memory:    16777216 KiB\\nEOF\\ncat > /tmp/ksm.log <<''EOF''\\npages_shared 1000\\npages_sharing 8000\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/reclaimed.txt)\\" = 16384 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "16384 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/reclaimed.txt)\\" = 16384 ]"]}]', '[{"title": "libvirt 메모리 balloon", "url": "https://libvirt.org/formatdomain.html#memory-balloon-device"}, {"title": "KSM 문서", "url": "https://docs.kernel.org/admin-guide/mm/ksm.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 6, 'KSM 으로 아낀 메모리', '`/tmp/ksm.log` 는 KSM(같은 내용의 페이지를 합치는 기능)의 통계입니다. `pages_shared` 는 합쳐진 공유 페이지 수, `pages_sharing` 은 그 페이지를 공유해 따로 쓰지 않아도 된 사이트 수로 **절약된 페이지 수**입니다. 페이지 하나는 **4KiB** 입니다. 절약된 메모리를 **MiB 로 소수점 이하를 버린 정수**로 `/tmp/ksm_mib.txt` 에 저장하세요.', '절약된 페이지 수에 페이지 크기를 곱해 KiB 로 바꾼 뒤 MiB 로 환산하세요. 곱하기를 먼저 해야 소수점이 잘리지 않습니다.', 'cat /tmp/ksm.log
A=$(grep pages_sharing /tmp/ksm.log | awk ''{print $2}'')
echo $(( A * 4 / 1024 )) > /tmp/ksm_mib.txt
cat /tmp/ksm_mib.txt

# 8000×4KiB = 32000KiB 로 약 31MiB 다. 같은 OS 이미지의 VM 이 많을수록 효과가 크지만 CPU 를 쓰고 보안 우려(사이드 채널)가 있어 신중히 쓴다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nEOF\\ncat > /tmp/free.log <<''EOF''\\n              total        used        free      shared  buff/cache   available\\nMem:         131072       72000       30000        1200       29000       57000\\nSwap:          8192           0        8192\\nEOF\\ncat > /tmp/vm_list.log <<''EOF''\\n Name    vCPU  Memory(MiB)  State\\n web01      4        8192   running\\n db01       8       32768   running\\n batch     24       16384   running\\n cache      4        8192   running\\nEOF\\ncat > /tmp/db01_info.log <<''EOF''\\nMax memory:     33554432 KiB\\nUsed memory:    16777216 KiB\\nEOF\\ncat > /tmp/ksm.log <<''EOF''\\npages_shared 1000\\npages_sharing 8000\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/ksm_mib.txt)\\" = 31 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "31 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ksm_mib.txt)\\" = 31 ]"]}]', '[{"title": "libvirt 메모리 balloon", "url": "https://libvirt.org/formatdomain.html#memory-balloon-device"}, {"title": "KSM 문서", "url": "https://docs.kernel.org/admin-guide/mm/ksm.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 7, 'CPU 오버커밋이 지나칠 때', 'vCPU 합계가 물리 CPU 보다 훨씬 많은 호스트에서 VM 안의 `%st`(steal)가 계속 높습니다. 가장 알맞은 해석과 대응은?', 'steal 은 VM 이 CPU 를 기다린 시간입니다.', NULL, NULL, '[]', 'choice', '["게스트의 디스크가 느려서 생기므로 디스크를 교체한다", "네트워크 지연이 원인이므로 NIC 를 새것으로 교체한다", "CPU 를 나눠 쓰느라 대기 중이니 VM 배치를 줄인다", "steal 은 무시해도 되는 지표라서 조치가 필요 없다"]', 2, 'steal 이 높으면 호스트의 물리 CPU 가 부족해 VM 이 실행 기회를 기다리는 것입니다. VM 을 다른 호스트로 옮기거나 vCPU 수·오버커밋 비율을 줄이고, 불필요하게 많이 준 vCPU 를 줄입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 8, '메모리 오버커밋의 위험', '호스트 메모리보다 훨씬 많은 메모리를 VM 에 할당해 두었는데 VM 들이 동시에 메모리를 많이 쓰기 시작했습니다. 가장 알맞은 결과는?', '호스트에 물리 메모리가 바닥나면 커널이 어떻게 하는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["호스트가 필요한 만큼 자동으로 메모리를 늘려 준다", "스왑으로 느려지다 OOM killer 가 VM 을 종료할 수 있다", "VM 이 모두 자동으로 일시정지되고 문제가 사라진다", "메모리 오버커밋은 어떤 경우에도 아무 위험이 없다"]', 1, '메모리는 CPU 와 달리 시간을 나눠 쓸 수 없어 부족하면 스왑으로 극심하게 느려지고 OOM killer 가 큰 프로세스(VM 의 qemu)를 종료할 수 있습니다. 메모리 오버커밋은 보수적으로 잡습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 602, 9, 'vCPU 수 바꾸기', '`virsh` 로 VM `web01` 의 vCPU 를 **4 개로 바꾸는** 하위 명령을 채우세요. (메모리를 바꾸는 `setmem` 과 구분)', '개수를 설정하는 `set` 계열 하위 명령 중 CPU 쪽입니다.', NULL, NULL, '[]', 'fill', '["setvcpus", "setmem", "vcpuinfo", "vcpucount"]', NULL, '`setvcpus` 는 vCPU 수를 바꾸고, `setmem` 은 메모리를 바꿉니다. `vcpuinfo` 는 vCPU 의 실행 정보, `vcpucount` 는 현재·최대 vCPU 수를 보여 줍니다. 실행 중 변경은 정의된 최대치 안에서만 가능합니다.', '[0]', 'virsh {0} web01 4 --live', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 602 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
